import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,D as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,b as u,j as d,k as f,p,w as m,x as h}from"./shared-DoR5oW6-.js";import{t as g}from"./git-branch--KUP4I0u.js";import{t as _}from"./key-round-D-Q1K68g.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=`data:image/svg+xml;base64,`,b=`data:image/svg+xml;base64,`,x=e();function S({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{chip:e??`Месяц 3 · Блок 10 · Первый FastAPI`,title:`54. Path-параметры и чтение одной задачи`,intro:`GET /tasks уже показывает реальные задачи Planner. Теперь клиент сможет запросить одну запись по её id, а API точно различит найденную задачу, отсутствие записи и неверный тип адреса.`,tags:[{icon:(0,x.jsx)(_,{size:14}),label:`id в адресе`},{icon:(0,x.jsx)(g,{size:14}),label:`200 · 404 · 422`}]}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`Прежняя опора`,description:`В прошлом занятии API прочитал реальные список и статистику Planner.`},{title:`Новый вопрос`,description:`Как адресовать одну запись и различить её отсутствие и неверный id?`},{title:`Результат`,description:`Добавим чтение item по path-параметру и проследим ответы 200, 404 и 422.`}]}),(0,x.jsxs)(s,{number:`00`,title:`Из списка открываем нужную задачу`,children:[(0,x.jsx)(o,{children:`В прошлом занятии Planner API научился возвращать список из рабочего JSON. На экране планировщика человек выбирает одну строку и ждёт, что откроется именно эта задача, а не весь список заново.`}),(0,x.jsx)(`p`,{children:`Для этого у каждой записи есть устойчивый id. Например, /tasks/17 просит задачу с id 17. Число здесь учебное: в практике мы возьмём настоящий id из ответа Planner.`}),(0,x.jsxs)(r,{tone:`info`,children:[(0,x.jsx)(`strong`,{children:`План занятия.`}),` Проследим адрес до Python-функции, передадим id готовому PlannerService и соберём ответ. Затем проверим, чем отличаются несуществующий id и значение, которое вообще нельзя прочитать как число.`]}),(0,x.jsx)(h,{question:`Если задача с id 17 есть в GET /tasks, какой результат ожидается от GET /tasks/17?`,answer:(0,x.jsx)(`p`,{children:`Одна задача с id 17. Адрес выбирает запись, а не повторно запрашивает весь список.`})})]}),(0,x.jsxs)(s,{number:`01`,title:`Path выбирает item, query настраивает список`,children:[(0,x.jsx)(o,{children:`Маршрут коллекции и маршрут одной записи похожи, но просят разный объём данных.`}),(0,x.jsx)(v,{caption:`один API, два масштаба чтения`,code:`GET /tasks                  → список задач
GET /tasks/17               → одна задача
GET /tasks?is_done=false    → список по условию`}),(0,x.jsx)(`p`,{children:`Collection, или коллекция, это набор задач. Item это один элемент набора. Ресурс API может обозначать и коллекцию, и отдельную Task. В нашем примере path указывает на ресурс, а query настраивает чтение списка.`}),(0,x.jsx)(`p`,{children:`Path находится в основном пути URL и называет ресурс. Query начинается после знака вопроса и задаёт настройки коллекции. Поэтому запрос с is_done=false всё ещё просит список, даже если ответ станет короче.`}),(0,x.jsx)(`p`,{children:`GET /tasks?is_done=false здесь показывает форму будущего запроса. Текущий обработчик GET /tasks ещё не подключил фильтр is_done, поэтому сам параметр в URL не означает, что отбор уже работает. Подключим query в следующем занятии.`}),(0,x.jsx)(`p`,{children:`Id не равен номеру строки. После сортировки задача может переместиться, но её id остаётся прежним. Именно поэтому ссылка на /tasks/17 продолжает указывать на одну и ту же запись.`}),(0,x.jsx)(p,{prompt:`Соединим адрес с тем, что просит клиент.`,leftTitle:`Адрес`,rightTitle:`Объект запроса`,pairs:[{left:`GET /tasks`,right:`Коллекция целиком`},{left:`GET /tasks/17`,right:`Один item с id 17`},{left:`GET /tasks?is_done=false`,right:`Коллекция с условием`}],explanation:`Число в path указывает на конкретную запись. Query меняет выборку, но не превращает коллекцию в item.`}),(0,x.jsx)(c,{statement:(0,x.jsx)(x.Fragment,{children:`Если задача с id 17 стоит третьей в ответе, маршрут /tasks/17 должен искать третий элемент списка.`}),isTrue:!1,explanation:`Id это идентификатор задачи, а не её текущая позиция. Сервис ищет запись по id.`})]}),(0,x.jsxs)(s,{number:`02`,title:`FastAPI проверяет path-параметр до вызова функции`,children:[(0,x.jsx)(o,{children:`Переменная часть адреса связывается с аргументом Python-функции по имени.`}),(0,x.jsx)(`p`,{children:`В шаблоне /books/{book_id} фигурные скобки отмечают место значения. Имя book_id должно совпасть с аргументом. Аннотация int сообщает FastAPI ожидаемый тип параметра.`}),(0,x.jsx)(v,{caption:`небольшой пример только для связи URL и функции`,code:`@app.get("/books/{book_id}")
def read_book(book_id: int):
    return {"requested_id": book_id}`}),(0,x.jsx)(`p`,{children:`Для GET /books/17 фреймворк берёт 17 из URL, проверяет значение и передаёт в read_book как целое число. Обработчик не обязан вручную разбирать строку. Если приходит abc, проверка останавливает запрос до входа в функцию.`}),(0,x.jsx)(m,{title:`Путь от URL к аргументу`,prompt:`Проследим этапы обработки GET /books/17.`,pieces:[{id:`extract`,code:`FastAPI извлекает значение из {book_id}`},{id:`validate`,code:`проверяет, что значение подходит типу int`},{id:`call`,code:`вызывает функцию с числом 17`}],correctOrder:[`extract`,`validate`,`call`],explanation:`Значение сначала извлекается, затем проверяется. Только после успешного разбора вызывается обработчик.`,incorrectExplanation:`Сначала FastAPI извлекает сегмент из URL, затем преобразует и проверяет его тип. Обработчик получает число только после успешной проверки.`}),(0,x.jsx)(`p`,{children:`Когда /tasks/abc не подходит типу int, FastAPI формирует 422. Это ошибка формы запроса. Сервис ещё не искал задачу, потому что маршрут не получил целочисленный id.`}),(0,x.jsx)(`p`,{children:`Числа 0 и -1 проходят преобразование в int, но нарушают правило Planner: id должен быть положительным. В HTTP-маршруте FastAPI проверяет это ограничение через Path(gt=0) и возвращает 422 до запуска обработчика и вызова сервиса. Сам PlannerService тоже проверяет положительность id, чтобы сохранить правило при прямых вызовах из CLI или другого кода. Это две независимые границы одной проверки. Текстовый abc останавливается раньше, на преобразовании в int; положительный id без задачи доходит до сервиса и даёт TaskNotFoundError, который маршрут переводит в 404.`}),(0,x.jsx)(`p`,{children:`Чтобы FastAPI проверил не только тип, но и диапазон пути, мы добавляем к int ограничение Path. gt означает «строго больше»: Path(gt=0) принимает положительные ID, но отклоняет ноль и отрицательные значения. Annotated связывает тип int с этим правилом для параметра маршрута.`}),(0,x.jsx)(v,{caption:`Фрагмент объявления положительного path-параметра`,code:`from typing import Annotated
from fastapi import Path

task_id: Annotated[int, Path(gt=0)]`}),(0,x.jsx)(`p`,{children:`FastAPI проверяет это ограничение до вызова read_task, поэтому ответ 422 формируется на HTTP-границе. PlannerService повторяет доменное правило для прямых вызовов из CLI или другого кода. Каждая граница защищает свой договор: API проверяет запрос, а сервис не допускает недопустимый ID независимо от клиента.`}),(0,x.jsx)(t,{code:`GET /tasks/abc

@app.get("/tasks/{task_id}")
def read_task(task_id: int):
    return app.state.planner.get_task(task_id)`,question:`Какой этап обработает abc?`,options:[`PlannerService получит строку и ответит 404`,`FastAPI вернёт 422 до вызова read_task`,`FastAPI преобразует abc в id 0`],correctIndex:1,explanation:`Объявленный int проверяется на границе запроса. При невозможном разборе функция и сервис не вызываются.`,fix:`Оставим task_id: int. Для неизвестного числового id обработаем отдельный результат сервиса в маршруте.`})]}),(0,x.jsxs)(s,{number:`03`,title:`Маршрут использует готовый поиск Planner`,children:[(0,x.jsx)(o,{children:`Когда тип значения проверен, маршрут передаёт id существующему сервису проекта.`}),(0,x.jsx)(`p`,{children:`PlannerService уже знает, как найти Task в настроенном хранилище. Мы не переписываем цикл поиска и не создаём второй список. app.state.planner содержит тот сервис, который подключили к API в прошлом занятии.`}),(0,x.jsx)(f,{variant:`connected`,items:[{title:`FastAPI`,description:`Извлекает task_id из path и передаёт целое число обработчику.`},{title:`PlannerService`,description:`Ищет доменную Task по id через существующий источник данных.`},{title:`Маршрут`,description:`Превращает результат сервиса в публичный HTTP-ответ.`}]}),(0,x.jsx)(v,{caption:`Путь данных без кода обработчика`,code:`task_id из URL → готовый PlannerService.get_task → Task или TaskNotFoundError → HTTP-ответ`}),(0,x.jsx)(`p`,{children:`В прошлом занятии мы уже подключили app.state.planner к реальным данным. Этот endpoint продолжает ту же цепочку: HTTP не получает копию задач при старте, а сервис выполняет операцию для текущего запроса.`}),(0,x.jsx)(h,{question:`Кто должен искать Task: обработчик маршрута или готовый PlannerService?`,answer:(0,x.jsx)(`p`,{children:`PlannerService. Маршрут связывает HTTP с операцией и формирует ответ.`})})]}),(0,x.jsxs)(s,{number:`04`,title:`Ожидаемое отсутствие превращается в 404`,children:[(0,x.jsx)(o,{children:`Корректный числовой id может не соответствовать ни одной записи. Это другой случай, чем неверный тип.`}),(0,x.jsx)(`p`,{children:`Если задача не найдена, готовый сервис сообщает TaskNotFoundError. Маршрут переводит именно эту ожидаемую доменную ошибку в HTTPException со статусом 404. Сервис при этом не обязан знать, что такое HTTP.`}),(0,x.jsx)(`p`,{children:`HTTPException предоставляет FastAPI. Импортируем его из пакета fastapi. Когда маршрут поднимает это исключение через raise, FastAPI прекращает обычный путь обработчика и формирует HTTP-ответ со статусом и описанием ошибки.`}),(0,x.jsx)(`p`,{children:`На независимом примере книг предположим, что catalog.get_book(book_id) сообщает BookNotFoundError, если книги нет. На HTTP-границе мы ловим именно это ожидаемое исключение и поднимаем HTTPException со статусом 404. FastAPI формирует ответ, а каталог не получает зависимость от HTTP.`}),(0,x.jsx)(v,{caption:`Независимый пример: отсутствие книги`,code:`from fastapi import HTTPException

try:
    book = catalog.get_book(book_id)
except BookNotFoundError as error:
    raise HTTPException(
        status_code=404,
        detail="Book not found",
    ) from error`}),(0,x.jsx)(`p`,{children:`Мы не перехватываем общий Exception. Например, сбой чтения повреждённого JSON не означает, что записи нет. Если превратить любую ошибку в 404, клиент и разработчик получат неверную причину сбоя.`}),(0,x.jsx)(t,{code:`GET /books/81
book_id успешно разобран как int
catalog сообщает BookNotFoundError
HTTP-ответ: 422`,question:`Книги с корректным числовым id нет. Что в этом ответе не совпадает с причиной?`,options:[`Для ожидаемого отсутствия книги нужен статус 404`,`Для любого отсутствия всегда нужен статус 422`,`Нужно превратить BookNotFoundError в успешный ответ`],correctIndex:0,explanation:`Числовой id прошёл проверку, но книга не найдена. 422 относится к неразбираемому или некорректному входу, а ожидаемое отсутствие ресурса обозначается 404.`,fix:`Заменим статус на 404 для BookNotFoundError и оставим обработку узкой: остальные сбои не маскируем.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Публичный ответ остаётся отдельным от модели`,children:[(0,x.jsx)(o,{children:`Внутренняя Task и JSON, который обещает API клиенту, связаны, но это не одно и то же.`}),(0,x.jsx)(`p`,{children:`Для этого API в публичную задачу входят id, title, priority и is_done. Например, tags остаётся во внутренней модели и в JSON-файле, но не добавляется в этот ответ автоматически.`}),(0,x.jsx)(`p`,{children:`Проекция это выбранное представление объекта для конкретного ответа. Мы собираем её явно, чтобы внутренние поля не меняли формат API сами по себе.`}),(0,x.jsx)(l,{question:`Как сохранить понятный и устойчивый формат GET /tasks/{task_id}?`,left:{title:`Явная проекция`,code:`id · title · priority · is_done`,note:`Маршрут выдаёт ровно согласованные поля.`},right:{title:`Вся внутренняя модель`,code:`task.to_dict()`,note:`Вместе с ответом могут уйти служебные поля, например tags.`},preferred:`left`,explanation:`Публичный API-контракт меняется осознанно. Новое внутреннее поле не должно само по себе появиться у всех клиентов.`}),(0,x.jsx)(`p`,{children:`GET только читает. Не вызываем save и не меняем Task внутри запроса. Повторное чтение не должно менять JSON или статистику Planner.`}),(0,x.jsx)(u,{question:`Во внутреннюю Task добавили поле reminder_at. Должно ли оно автоматически попасть в HTTP-ответ?`,options:[`Да, любая модель целиком становится контрактом`,`Нет, список публичных полей задан явно`],correctIndex:1,explanation:`Явная проекция отделяет внутреннюю модель от обещания API. Новое поле добавляют наружу только отдельным решением.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Один адрес проходит проверку и даёт один исход`,children:[(0,x.jsx)(o,{children:`Теперь соединим маршрут, валидацию, поиск и ответ. Разница между 404 и 422 становится видна по месту, где остановился запрос.`}),(0,x.jsxs)(`figure`,{className:`lesson-infographic lesson-infographic--lesson54`,children:[(0,x.jsxs)(`picture`,{children:[(0,x.jsx)(`source`,{media:`(max-width: 640px)`,srcSet:b}),(0,x.jsx)(`img`,{src:y,alt:`FastAPI разбирает task_id как int и отклоняет нулевой или отрицательный ID через Path(gt=0) до обработчика. Найденная Task становится публичным ответом 200, отсутствие положительной задачи даёт 404, а неразбираемый или неположительный ID получает 422. Сбой хранилища не маскируется как 404.`,width:1672,height:620,loading:`lazy`,decoding:`async`})]}),(0,x.jsx)(`figcaption`,{children:`Сначала проверяется тип path-параметра. Только корректное число доходит до PlannerService; отсутствие задачи и ошибка хранилища остаются разными исходами.`})]}),(0,x.jsxs)(`div`,{className:`lesson-check-group`,children:[(0,x.jsx)(u,{question:`Куда дойдёт запрос GET /tasks/abc?`,options:[`До сервиса, который вернёт 404`,`Остановится на проверке FastAPI и получит 422`,`Будет преобразован в id 0`],correctIndex:1,explanation:`Обработчик вызывается только после успешного преобразования значения в int.`}),(0,x.jsx)(u,{question:`Сервис сообщил TaskNotFoundError для id 999. Какой ответ отправляет маршрут?`,options:[`404, ресурс не найден`,`422, параметр не разобран`,`200 с первой записью`],correctIndex:0,explanation:`Число корректно, но соответствующей задачи нет. Это отсутствие ресурса, а не ошибка типа.`}),(0,x.jsx)(c,{statement:(0,x.jsx)(x.Fragment,{children:`Ошибка чтения JSON должна превращаться в 404, если клиент запросил конкретный id.`}),isTrue:!1,explanation:`Сбой хранилища не доказывает, что задачи нет. Его нельзя маскировать как ожидаемое отсутствие.`})]}),(0,x.jsx)(n,{points:[(0,x.jsx)(x.Fragment,{children:`Path с id выбирает один item, а query настраивает чтение коллекции.`}),(0,x.jsx)(x.Fragment,{children:`FastAPI разбирает task_id и отклоняет id 0 или меньше по Path(gt=0), до вызова обработчика; сервис отдельно защищает своё правило для прямых вызовов.`}),(0,x.jsx)(x.Fragment,{children:`PlannerService ищет Task, а маршрут превращает TaskNotFoundError в 404.`}),(0,x.jsx)(x.Fragment,{children:`Явная проекция возвращает четыре поля и сохраняет GET read-only.`})]})]}),(0,x.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Мы добавим в существующий Planner API чтение одной реальной задачи. Это продолжение работающего проекта, а не отдельное упражнение на временном списке.`}),(0,x.jsx)(`p`,{children:`В первом задании добавим GET /tasks/{task_id} в app/api.py. Path-параметр попадёт в готовый app.state.planner.get_task(task_id), а ответ будет содержать согласованные публичные поля Task.`}),(0,x.jsx)(`p`,{children:`Во втором задании изменим уже созданный обработчик read_task, не добавляя второй маршрут с той же парой GET и /tasks/{task_id}. Проверим существующий id, отсутствующий положительный id, abc, 0 и -1. Ожидаемые результаты: 200, 404 и 422; FastAPI отклонит abc при разборе int, а 0 и -1 по Path(gt=0), до вызова сервиса. После чтения повторно сравним список, статистику и рабочий JSON. Запросы останутся в уже существующей Planner collection.`}),(0,x.jsxs)(r,{tone:`info`,children:[(0,x.jsx)(`strong`,{children:`Граница работы.`}),` Мы не создаём второй список задач, не пишем новый поиск и не меняем хранилище. Мы добавляем только HTTP-маршрут к уже готовой операции.`]}),(0,x.jsx)(d,{text:`Добавим GET /tasks/{task_id}, подключим его к PlannerService и проверим найденную задачу, 404, 422 и сохранность данных.`})]})]})}export{S as Lesson54};